-- Siembra de las 34 actividades clínicas de business/INTEGRAMENTE_EN_CASA_CONTENIDOS.md.
-- Generado programáticamente a partir del documento fuente (no retipeado a mano) para no
-- introducir errores en contenido clínico validado. Texto literal del documento; los ~12
-- "objetivo esperado" genéricos y las evidencias sin cita bibliográfica formal quedan tal
-- cual el documento los trae (ver su propia sección "Pendientes de contenido detectados").
insert into public.media_resources
  (codigo, titulo, modulo, tipo, tipo_intervencion, dominios, duracion, duracion_min, duracion_max,
   frecuencia, perfil, requisito, objetivo, materiales, pasos, progresion, adaptacion, precaucion,
   ciencia, por_que, activo)
values
  ('SEN-001', 'Entrenamiento olfativo de cuatro aromas', 'sentidos'::public.resource_modulo, 'actividad'::public.task_tipo, 'olfativa', array['olfato','atención sostenida','discriminación','acceso semántico']::text[], '8-10 min', 8, 10, '2 veces/semana o según plan individual', 'Preventivo, DCL y demencia leve con capacidad para seguir una rutina breve.', 'Puede identificar o describir sensaciones y tolera aromas sin malestar.', 'Entrenar discriminación olfativa y atención mediante exposición repetida y estructurada.', 'Cuatro aromas seguros y diferenciables: por ejemplo café, limón/naranja, canela y vainilla.', '["Presentar un aroma a la vez, sin acercarlo excesivamente a la nariz.", "Pedir que lo huela durante unos segundos y describa intensidad, agrado y familiaridad.", "Repetir con los cuatro aromas, evitando corregir de inmediato.", "Registrar cuáles reconoce y cuáles discrimina con mayor facilidad.", "Repetir con regularidad según el plan asignado por la app."]'::jsonb, 'De describir sensaciones → discriminar aromas → identificar → recordar el orden de presentación.', 'En demencia leve reducir a dos aromas y ofrecer opciones. Si no puede nombrar, aceptar descripciones o asociaciones.', 'No comunicarlo como una estrategia demostrada para prevenir Alzheimer. Utilizar aromas seguros y conocidos.', '{"gancho": "🧠 ¿Sabías que entrenar el olfato también puede ayudarnos a mantener la atención y reconocer diferentes aromas?", "evidencia": "Un estudio de TU Dresden con 91 adultos mayores encontró mejoras en la capacidad olfativa después de varios meses de entrenamiento. 👃✨", "cierre": "¡Por eso hoy vamos a ejercitar nuestra atención y nuestro olfato descubriendo y diferenciando diferentes aromas!"}'::jsonb, 'Favorecer el entrenamiento de discriminación olfativa y atención mediante exposición repetida y estructurada.', true),
  ('SEN-002', '¿Igual o diferente?', 'sentidos'::public.resource_modulo, 'actividad'::public.task_tipo, 'olfativa', array['discriminación','atención selectiva','decisión']::text[], '8-10 min', 8, 10, '2 veces/semana o según plan individual', 'Preventivo, DCL y demencia leve.', 'Comprende comparación simple entre dos estímulos.', 'Trabajar discriminación sensorial, atención y comparación.', 'Dos a cuatro recipientes con pares de aromas.', '["Presentar dos aromas consecutivos.", "Preguntar únicamente: ¿son iguales o diferentes?", "Después pedir que explique en qué se parecen o diferencian.", "En una segunda ronda, mezclar pares iguales y diferentes."]'::jsonb, 'Dos aromas claramente distintos → aromas más parecidos → cuatro presentaciones con recuerdo de posición.', 'En demencia leve usar contrastes muy claros y respuestas binarias.', 'Evitar sesiones largas: la adaptación olfativa puede disminuir la percepción de los aromas.', '{"gancho": "🧠 ¿Sabías que entrenar el olfato puede ayudarnos a mejorar nuestra capacidad para distinguir diferentes aromas?", "evidencia": "Las revisiones actuales muestran que el entrenamiento olfativo mejora de forma consistente la capacidad para reconocer y diferenciar olores. 👃✨", "cierre": "¡Por eso hoy vamos a poner a prueba nuestra atención selectiva, comparación y capacidad de decisión descubriendo si dos aromas son iguales o diferentes!"}'::jsonb, 'Favorecer discriminación sensorial, atención y comparación.', true),
  ('SEN-003', 'Aroma → palabra', 'sentidos'::public.resource_modulo, 'actividad'::public.task_tipo, 'olfativa + lenguaje', array['acceso léxico','fluencia semántica','atención','olfato']::text[], '8-10 min', 8, 10, '2 veces/semana o según plan individual', 'Preventivo, DCL y demencia leve.', 'Puede producir lenguaje espontáneo o responder con claves.', 'Usar el olor como vehículo para trabajar acceso léxico, semántica y fluencia.', 'Café, canela, cítrico, vainilla u otros aromas culturalmente familiares.', '["Presentar el aroma sin mostrar su fuente.", "Preguntar: ¿le resulta familiar?, ¿cómo lo describiría?", "Solicitar el nombre solo después de explorar sensaciones y asociaciones.", "Una vez identificado o revelado, pedir tres palabras relacionadas con ese aroma."]'::jsonb, 'Pedir más asociaciones → categorías semánticas → 30 segundos de producción de palabras relacionadas.', 'Ofrecer dos opciones o una pista semántica si no aparece la palabra.', 'Evitar corregir con rapidez. Reconocer un olor y poder nombrarlo no son procesos equivalentes.', '{"gancho": "🧠 ¿Sabías que un aroma puede ayudarnos a encontrar palabras con mayor facilidad?", "evidencia": "Un estudio de 2025 con 128 adultos mayores encontró mejoras en la fluidez verbal después del entrenamiento olfativo. 👃🗣️✨", "cierre": "¡Por eso hoy vamos a estimular nuestra atención y nuestras palabras a través de los aromas y sus asociaciones!"}'::jsonb, 'Favorecer una participación segura y significativa mediante esta actividad.', true),
  ('SEN-004', 'Un aroma, una historia', 'sentidos'::public.resource_modulo, 'actividad'::public.task_tipo, 'reminiscencia olfativa', array['memoria autobiográfica','lenguaje','emoción','identidad','conexión familiar']::text[], '8-10 min', 8, 10, '2 veces/semana o según plan individual', 'DCL, demencia leve y moderada; también preventivo con objetivo autobiográfico.', 'Existe información biográfica suficiente para escoger aromas significativos.', 'Facilitar evocación autobiográfica, conversación e identidad mediante claves olfativas.', 'Un aroma significativo: café, jabón, perfume, especia, flor, alimento, madera, etc.', '["Presentar el aroma sin pedir que lo identifique.", "Preguntar qué sensación le produce.", "Explorar si aparece un lugar, persona, época o actividad.", "Si no recuerda, ofrecer una clave: «Este era el café que tomábamos en casa…».", "Validar palabras, gestos, emociones y expresiones, no solo historias completas."]'::jsonb, 'Una asociación → varias preguntas contextuales → combinar con foto u objeto relacionado.', 'En demencia moderada usar preguntas concretas, una a la vez, y aportar información en lugar de examinar.', 'Si el aroma provoca tristeza o angustia sostenida, retirarlo y cambiar a un estímulo neutro/agradable.', '{"gancho": "🧠 ¿Sabías que un aroma puede ayudarnos a despertar recuerdos y emociones de momentos importantes de nuestra vida?", "evidencia": "La investigación muestra que la estimulación olfativa puede favorecer el bienestar y la conexión con experiencias personales. 👃❤️✨", "cierre": "¡Por eso hoy vamos a estimular nuestros recuerdos, emociones y conversación a través de un aroma especial!"}'::jsonb, 'Favorecer evocación autobiográfica, conversación e identidad mediante claves olfativas.', true),
  ('SEN-005', 'La bolsa de las texturas', 'sentidos'::public.resource_modulo, 'actividad'::public.task_tipo, 'táctil', array['tacto','reconocimiento','lenguaje descriptivo','memoria semántica','praxias']::text[], '8-10 min', 8, 10, '2 veces/semana o según plan individual', 'Todos los niveles, con adaptación.', 'Puede explorar objetos con la mano y mantener atención al menos brevemente.', 'Trabajar reconocimiento táctil, lenguaje descriptivo, función del objeto y asociaciones autobiográficas.', 'Bolsa opaca; squishy, cuchara de madera, algodón, tela, esponja, objeto metálico grande y seguro.', '["Introducir una mano sin mirar.", "Pedir que describa primero la sensación: suave, duro, frío, blando, rugoso, etc.", "Preguntar qué podría ser o para qué podría servir.", "Extraer el objeto y conversar sobre la asociación que haya aparecido."]'::jsonb, 'Texturas muy distintas → objetos de función similar → recordar el orden de los objetos.', 'En demencia moderada no pedir el nombre: mostrar el objeto, modelar el gesto y preguntar por su uso o historia.', 'Usar objetos grandes, limpios y no cortantes. Supervisar si existe conducta de exploración oral.', '{"gancho": "🧠 ¿Sabías que explorar diferentes texturas puede activar nuestros sentidos y ayudarnos a reconocer y describir lo que tocamos?", "evidencia": "Las revisiones recientes sobre estimulación multisensorial han encontrado beneficios en la participación y el bienestar de personas con demencia. ✋✨", "cierre": "¡Por eso hoy vamos a estimular el tacto, el reconocimiento, el lenguaje y nuestras habilidades para manipular objetos a través de diferentes texturas!"}'::jsonb, 'Favorecer reconocimiento táctil, lenguaje descriptivo, función del objeto y asociaciones autobiográficas.', true),
  ('SEN-006', 'Objeto → gesto → historia', 'sentidos'::public.resource_modulo, 'actividad'::public.task_tipo, 'táctil + praxias + reminiscencia', array['praxias','memoria semántica','reconocimiento','reminiscencia','comunicación']::text[], '8-10 min', 8, 10, '2 veces/semana o según plan individual', 'Demencia leve, moderada y avanzada con objetos muy familiares.', 'Conserva capacidad de manipular o imitar gestos simples.', 'Acceder a conocimiento funcional y recuerdos aun cuando el nombre del objeto no aparezca.', 'Cuchara de madera, peine, cartera, brocha, paño, utensilio de oficio seguro.', '["Entregar el objeto y permitir exploración.", "Preguntar: «¿Qué hacemos con esto?» antes de preguntar su nombre.", "Si no responde, modelar el gesto asociado.", "Conectar con una pregunta biográfica sencilla: «¿Quién cocinaba en su casa?»."]'::jsonb, 'Objeto visible → objeto solo por tacto → secuencia de dos objetos y acciones.', 'En demencia avanzada centrarse en manipulación, gesto y emoción; omitir demandas verbales.', 'Elegir objetos ligados a la historia de vida y evitar elementos que puedan producir daño.', '{"gancho": "🧠 ¿Sabías que un objeto conocido puede ayudarnos a recordar cómo se usa, incluso cuando cuesta encontrar su nombre?", "evidencia": "La estimulación multisensorial puede favorecer la participación, la comunicación y el bienestar, incluso cuando la respuesta verbal es limitada. ✋🧠✨", "cierre": "¡Por eso hoy vamos a estimular el reconocimiento, la memoria, las acciones y la comunicación a través de objetos conocidos!"}'::jsonb, 'Favorecer el acceso a conocimiento funcional y recuerdos aun cuando el nombre del objeto no aparezca.', true),
  ('SEN-007', 'Café y lluvia', 'sentidos'::public.resource_modulo, 'actividad'::public.task_tipo, 'multisensorial', array['integración multisensorial','memoria autobiográfica','lenguaje','emoción','atención']::text[], '8-10 min', 8, 10, '2 veces/semana o según plan individual', 'Todos los niveles; especialmente DCL y demencia leve-moderada.', 'Tolera varios estímulos cuando se presentan de manera gradual.', 'Integrar claves visuales, auditivas, táctiles y olfativas para facilitar asociaciones y conversación.', 'Imagen de cocina/mesa tradicional, audio de lluvia, taza de cerámica, aroma de café.', '["Mostrar únicamente la imagen y preguntar qué sugiere.", "Agregar el sonido de lluvia y observar qué cambia en la historia.", "Entregar la taza y explorar la sensación.", "Agregar el aroma de café.", "Preguntar qué lugar, persona o momento aparece ahora."]'::jsonb, 'Dos sentidos → tres → cuatro; en niveles altos pedir después recordar qué elementos se presentaron.', 'En demencia moderada usar solo dos estímulos coherentes y permitir respuestas emocionales o gestuales.', 'Más estímulos no significa mejor estimulación. Introducirlos uno por uno y detener ante signos de sobrecarga.', '{"gancho": "🧠 ¿Sabías que combinar diferentes sentidos puede ayudarnos a despertar recuerdos, emociones y asociaciones?", "evidencia": "Un meta-análisis de 2025 con 974 personas con demencia encontró beneficios de la estimulación multisensorial en la función mental general. ☕🌧️🧠✨", "cierre": "¡Por eso hoy vamos a estimular nuestra atención, memoria, lenguaje y emociones a través de una experiencia llena de sensaciones!"}'::jsonb, 'Favorecer la integración de claves visuales, auditivas, táctiles y olfativas para facilitar asociaciones y conversación.', true),
  ('SEN-008', 'Escena sensorial personalizada', 'sentidos'::public.resource_modulo, 'actividad'::public.task_tipo, 'multisensorial + reminiscencia', array['regulación','orientación afectiva','atención','vínculo','reminiscencia']::text[], '10-15 min', 10, 15, '2 veces/semana o según plan individual', 'Demencia moderada/avanzada y personas con lenguaje limitado.', 'Familia conoce una actividad significativa de la vida de la persona.', 'Crear una experiencia sensorial segura que favorezca conexión y regulación, sin exigir rendimiento.', '2-3 estímulos coherentes con una escena biográfica: jardín, cocina, playa, misa, trabajo, etc.', '["Elegir una escena significativa.", "Preparar máximo tres estímulos relacionados.", "Presentarlos lentamente y observar respuestas.", "Nombrar la experiencia por la persona: «Esto es olor a café…», «Escuche la lluvia…».", "Conversar solo si la persona muestra interés; no forzar evocación."]'::jsonb, 'En personas con mayor capacidad agregar elección o preguntas autobiográficas.', 'En demencia avanzada mantener 1-2 estímulos, voz calmada y tiempo de observación.', 'No llamar a esta actividad «sesión Snoezelen» si no se realiza en un entorno/protocolo especializado; es una experiencia domiciliaria inspirada en principios multisensoriales.', '{"gancho": "🧠 ¿Sabías que una experiencia sensorial personalizada puede ayudarnos a conectar con recuerdos, emociones y momentos significativos?", "evidencia": "Las revisiones sobre estimulación multisensorial han encontrado beneficios especialmente relacionados con el bienestar, el estado de ánimo y la conducta. 🌿❤️✨", "cierre": "¡Por eso hoy vamos a estimular nuestra atención, emociones, recuerdos y vínculo a través de una experiencia sensorial especial!"}'::jsonb, 'Favorecer una experiencia que permita una experiencia sensorial segura que favorezca conexión y regulación, sin exigir rendimiento.', true),
  ('MOV-001', 'Caminar y nombrar', 'movimiento'::public.resource_modulo, 'actividad'::public.task_tipo, 'dual task motor-cognitivo', array['atención dividida','fluencia','función ejecutiva','marcha']::text[], '10-15 min', 10, 15, '2 veces/semana o según plan individual', 'Preventivo, DCL, demencia leve. Motor Verde o Amarillo.', 'Camina de forma segura con o sin supervisión y puede producir categorías simples.', 'Entrenar atención dividida, fluencia y control de marcha en tarea dual.', 'Espacio despejado; opcional conos.', '["Caminar a ritmo cómodo.", "Agregar una categoría sencilla: animales, frutas, ciudades, nombres.", "Priorizar marcha segura y palabras correctas; no competir.", "Detener la tarea cognitiva si la marcha se vuelve insegura."]'::jsonb, 'Categorías fáciles → alternar categorías → caminar entre conos → cambiar dirección por señal.', 'Motor Amarillo: acompañamiento cercano. Motor Rojo: marcha sentada alternando pies mientras nombra.', 'Seguridad motora tiene prioridad absoluta. Si hablar altera notablemente la marcha, reducir dificultad.', '{"gancho": "🧠 ¿Sabías que combinar caminar con una tarea mental puede ayudar a entrenar la atención y la capacidad para realizar dos cosas a la vez?", "evidencia": "Una revisión de 32 ensayos encontró beneficios de este tipo de entrenamiento en habilidades mentales y en la forma de caminar. 🚶‍♀️🧠✨", "cierre": "¡Por eso hoy vamos a estimular nuestra atención, fluidez, organización y forma de caminar mientras caminamos y nombramos palabras!"}'::jsonb, 'Favorecer el entrenamiento de atención dividida, fluencia y control de marcha en tarea dual.', true),
  ('MOV-002', 'Palma, cruce y señal', 'movimiento'::public.resource_modulo, 'actividad'::public.task_tipo, 'coordinación + inhibición', array['coordinación bilateral','secuenciación','inhibición','flexibilidad']::text[], '10-15 min', 10, 15, '2 veces/semana o según plan individual', 'Preventivo, DCL y demencia leve. Puede realizarse sentado.', 'Comprende secuencias de 2-3 pasos.', 'Trabajar coordinación bilateral, secuenciación, inhibición y flexibilidad.', 'Ninguno.', '["Realizar una palma.", "Tocar con mano derecha rodilla izquierda y luego mano izquierda rodilla derecha.", "Agregar una señal verbal: cuando el familiar diga «cambio», invertir el orden.", "Practicar lento antes de aumentar velocidad."]'::jsonb, 'Dos movimientos → tres → respuesta a señal → alternar regla cada 30-60 segundos.', 'Demencia leve: imitación frente a frente. Motor Rojo: toda la secuencia sentada.', 'Evitar velocidad excesiva. El objetivo es coordinación correcta, no rendimiento deportivo.', '{"gancho": "🧠 ¿Sabías que realizar movimientos coordinados siguiendo diferentes señales puede ayudarnos a mejorar nuestra capacidad para adaptarnos y cambiar de una acción a otra?", "evidencia": "Las revisiones sobre ejercicio en personas con deterioro cognitivo muestran que combinar movimiento y retos mentales puede favorecer habilidades como la atención y el control de nuestras respuestas. 👐🧠✨", "cierre": "¡Por eso hoy vamos a estimular nuestra coordinación, memoria, atención y capacidad para adaptarnos con diferentes movimientos!"}'::jsonb, 'Favorecer coordinación bilateral, secuenciación, inhibición y flexibilidad.', true),
  ('MOV-003', 'Pelota y categorías', 'movimiento'::public.resource_modulo, 'actividad'::public.task_tipo, 'dual task sentado o de pie', array['atención','fluencia','coordinación óculo-manual','inhibición']::text[], '10-15 min', 10, 15, '2 veces/semana o según plan individual', 'Preventivo, DCL, demencia leve-moderada; Motor Verde/Amarillo/Rojo.', 'Puede lanzar/recibir una pelota blanda o rodarla sobre mesa.', 'Combinar coordinación visomotora con acceso semántico y atención.', 'Pelota blanda.', '["Lanzar o pasar la pelota entre dos personas.", "Cada vez que recibe, decir una palabra de una categoría.", "Si se repite una palabra, simplemente dar una pista y continuar.", "En demencia moderada usar nombres de personas conocidas o colores."]'::jsonb, 'Aumentar distancia → alternar dos categorías → cambiar dirección de pase por señal.', 'Motor Rojo: rodar pelota sobre mesa. Cognitivo moderado: familiar dice la categoría y ofrece dos opciones.', 'Usar pelota liviana y espacio libre de obstáculos.', '{"gancho": "🧠 ¿Sabías que combinar una actividad física con un reto mental puede ayudarnos a trabajar nuestras habilidades mentales y físicas al mismo tiempo?", "evidencia": "Los meta-análisis en adultos mayores con deterioro cognitivo han encontrado beneficios de este tipo de entrenamiento en la cognición y el desempeño físico. 🏐🧠✨", "cierre": "¡Por eso hoy vamos a estimular nuestra atención, fluidez, coordinación y capacidad para controlar nuestras respuestas mientras jugamos con la pelota!"}'::jsonb, 'Favorecer la combinación de coordinación visomotora con acceso semántico y atención.', true),
  ('MOV-004', 'Secuencia en movimiento', 'movimiento'::public.resource_modulo, 'actividad'::public.task_tipo, 'memoria de trabajo + coordinación', array['memoria de trabajo','secuenciación','praxias','atención']::text[], '10-15 min', 10, 15, '2 veces/semana o según plan individual', 'Preventivo, DCL, demencia leve.', 'Puede imitar 2 movimientos consecutivos.', 'Entrenar memoria de trabajo, secuenciación y aprendizaje motor.', 'Ninguno o tarjetas con movimientos.', '["Familiar realiza dos movimientos: palma + tocar hombros.", "Persona los imita en el mismo orden.", "Agregar un tercer movimiento cuando domine la secuencia.", "Repetir y luego cambiar la secuencia."]'::jsonb, '2 → 3 → 4 movimientos; después invertir el orden.', 'Demencia leve: mantener 1-2 movimientos y utilizar aprendizaje por imitación sin error.', 'No aumentar longitud si cae la precisión. Volver al último nivel exitoso.', '{"gancho": "🧠 ¿Sabías que recordar y repetir una secuencia de movimientos puede ayudarnos a entrenar nuestra memoria?", "evidencia": "La investigación sobre entrenamiento motor-cognitivo ha encontrado beneficios en diferentes habilidades mentales y físicas. 🧠🙌✨", "cierre": "¡Por eso hoy vamos a estimular nuestra memoria, atención, capacidad para seguir pasos y coordinación mientras aprendemos y repetimos movimientos!"}'::jsonb, 'Favorecer el entrenamiento de memoria de trabajo, secuenciación y aprendizaje motor.', true),
  ('MOV-005', 'Sentarse, levantarse y recordar', 'movimiento'::public.resource_modulo, 'actividad'::public.task_tipo, 'funcional + memoria', array['fuerza funcional','memoria de trabajo/reciente','atención']::text[], '10-15 min', 10, 15, '2 veces/semana o según plan individual', 'Preventivo, DCL; Motor Verde o Amarillo con capacidad segura de sit-to-stand.', 'Puede levantarse de una silla estable sin dolor importante.', 'Combinar fuerza funcional de miembros inferiores con memoria de trabajo.', 'Silla firme con respaldo, idealmente contra pared.', '["Mostrar 2-3 palabras u objetos.", "Realizar 3-5 repeticiones lentas de sentarse y levantarse.", "Al finalizar, pedir que recuerde los elementos.", "Dar claves si es necesario y registrar nivel de ayuda."]'::jsonb, 'Más elementos → mayor intervalo → categoría distractora durante el movimiento.', 'Motor Amarillo: apoyo de brazos/supervisión. Motor Rojo: extensión alterna de rodillas sentado y luego evocación.', 'No prescribir número de repeticiones rígido desde la app si no se conoce la capacidad física. Usar rangos y criterios de detención.', '{"gancho": "🧠 ¿Sabías que la actividad física regular también puede beneficiar la salud de nuestro cerebro?", "evidencia": "La OMS recomienda que las personas mayores realicen ejercicios de fortalecimiento y actividades que combinen diferentes tipos de movimiento, adaptadas a sus capacidades. 🪑🧠✨", "cierre": "¡Por eso hoy vamos a estimular nuestra fuerza, memoria y atención mientras nos sentamos, nos levantamos y recordamos!"}'::jsonb, 'Favorecer la combinación de fuerza funcional de miembros inferiores con memoria de trabajo.', true),
  ('MOV-006', 'Ruta con instrucciones', 'movimiento'::public.resource_modulo, 'actividad'::public.task_tipo, 'orientación + funciones ejecutivas', array['planificación','orientación espacial','memoria de trabajo','movilidad']::text[], '10-15 min', 10, 15, '2 veces/semana o según plan individual', 'Preventivo, DCL, demencia leve; Motor Verde/Amarillo.', 'Puede desplazarse en casa con seguridad.', 'Trabajar planificación, memoria de instrucciones y orientación espacial funcional.', '3 puntos seguros de la casa.', '["Dar una instrucción funcional de dos pasos: «Vaya a la mesa y luego a la puerta».", "Cuando la complete, agregar un tercer punto.", "Después pedir que explique qué ruta realizó."]'::jsonb, '2 pasos → 3 pasos → incorporar un objeto a transportar → cambio de regla.', 'Demencia leve: una instrucción a la vez y apoyo gestual.', 'Usar únicamente rutas familiares, iluminadas y sin desniveles.', '{"gancho": "🧠 ¿Sabías que combinar movimiento y retos mentales puede ayudarnos a practicar habilidades que usamos todos los días?", "evidencia": "Este tipo de entrenamiento se acerca a situaciones reales en las que necesitamos caminar, recordar y tomar decisiones al mismo tiempo. 🚶‍♀️🧠✨", "cierre": "¡Por eso hoy vamos a estimular nuestra planificación, memoria, orientación y movilidad mientras seguimos una ruta!"}'::jsonb, 'Favorecer planificación, memoria de instrucciones y orientación espacial funcional.', true),
  ('MOV-007', 'Equilibrio y búsqueda mental', 'movimiento'::public.resource_modulo, 'actividad'::public.task_tipo, 'balance + cognición', array['balance','atención dividida','función ejecutiva','fluencia']::text[], '10-15 min', 10, 15, '2 veces/semana o según plan individual', 'Preventivo y DCL; Motor Verde o Amarillo.', 'Puede mantener postura con base reducida de manera segura o con apoyo.', 'Combinar control postural con búsqueda semántica y atención.', 'Superficie firme; respaldo de silla o baranda.', '["Adoptar postura segura con pies juntos o semitándem, con apoyo disponible.", "Nombrar elementos de una categoría durante 20-30 segundos.", "Descansar y repetir.", "El familiar observa estabilidad y prioriza seguridad."]'::jsonb, 'Base amplia → pies juntos → semitándem; categorías fáciles → alternancia.', 'Motor Amarillo: mano en apoyo. Motor Rojo: sentado, elevar alternadamente talones/puntas mientras nombra.', 'Esta actividad requiere filtros de riesgo de caída en la app. Si existe duda, asignar versión sentada.', '{"gancho": "🧠 ¿Sabías que combinar el equilibrio con una tarea mental puede ayudarnos a trabajar nuestras habilidades físicas y mentales al mismo tiempo?", "evidencia": "Las revisiones sobre entrenamiento dual han encontrado beneficios en el equilibrio y otras habilidades relacionadas con el movimiento. ⚖️🧠✨", "cierre": "¡Por eso hoy vamos a estimular nuestro equilibrio, atención, fluidez y capacidad para organizar nuestras respuestas mientras buscamos palabras!"}'::jsonb, 'Favorecer la combinación de control postural con búsqueda semántica y atención.', true),
  ('MOV-008', 'Tarea funcional doble', 'movimiento'::public.resource_modulo, 'actividad'::public.task_tipo, 'dual task ecológico', array['funciones ejecutivas','atención dividida','autonomía funcional','memoria']::text[], '10-15 min', 10, 15, '2 veces/semana o según plan individual', 'DCL y demencia leve; Motor Verde/Amarillo.', 'Realiza actividades domésticas simples con seguridad.', 'Transferir el entrenamiento a actividades cotidianas reales.', 'Actividad segura: doblar paños, ordenar cubiertos no filosos, regar plantas, guardar objetos.', '["Elegir una tarea doméstica conocida.", "Agregar una demanda cognitiva simple: conversar sobre una categoría, recordar 2 elementos o seguir una regla.", "Observar si la tarea funcional pierde precisión.", "Reducir la carga cognitiva si aparecen errores o frustración."]'::jsonb, 'Tarea simple → doble regla → secuencia funcional de varios pasos.', 'Demencia leve: una regla y modelado. Moderada: mantener solo el componente funcional acompañado.', 'Excluir actividades con fuego, cuchillos, escaleras o riesgo de derrame/caída.', '{"gancho": "🧠 ¿Sabías que practicar una tarea cotidiana mientras realizamos una actividad mental puede ayudarnos a entrenar habilidades que usamos en la vida diaria?", "evidencia": "Las revisiones recientes sobre entrenamiento dual han encontrado beneficios en la cognición y la movilidad. 🏠🧠✨", "cierre": "¡Por eso hoy vamos a estimular nuestra atención, memoria, autonomía y capacidad para organizar nuestras acciones mientras realizamos una tarea cotidiana!"}'::jsonb, 'Favorecer una participación segura y significativa mediante esta actividad.', true),
  ('MUS-001', 'Mi canción, mi historia', 'musica'::public.resource_modulo, 'actividad'::public.task_tipo, 'música + reminiscencia', array['memoria autobiográfica','emoción','lenguaje','identidad']::text[], '8-10 min', 8, 10, '2 veces/semana o según plan individual', 'DCL y demencia leve-moderada; también preventivo.', 'Existe información sobre preferencias musicales o canciones significativas.', 'Facilitar recuerdos autobiográficos, conversación, emoción e identidad.', '1-3 canciones significativas de distintas etapas.', '["Elegir una canción conocida y reproducir un fragmento breve.", "Preguntar qué sensación genera antes de preguntar por recuerdos.", "Explorar lugar, época, personas o actividades asociadas.", "Si no recuerda, aportar contexto y permitir escuchar sin exigencia."]'::jsonb, 'Una canción → comparar dos épocas → crear una pequeña línea de vida musical.', 'Demencia moderada: preguntas cerradas o comentarios del familiar; aceptar canto, movimiento o expresión facial.', 'Personalizar la selección. La música «de la época» no sustituye conocer las preferencias reales de la persona.', '{"gancho": "🧠 ¿Sabías que escuchar una canción significativa puede ayudarnos a conectar con recuerdos y emociones de nuestra historia?", "evidencia": "Una revisión sistemática de 2026 encontró beneficios de la reminiscencia musical especialmente en el bienestar, la participación y la conexión con los demás. 🎵❤️", "cierre": "¡Por eso hoy vamos a estimular nuestros recuerdos, emociones, lenguaje e identidad a través de una canción especial!"}'::jsonb, 'Favorecer recuerdos autobiográficos, conversación, emoción e identidad.', true),
  ('MUS-002', 'Completa la canción', 'musica'::public.resource_modulo, 'actividad'::public.task_tipo, 'música + lenguaje', array['lenguaje','atención auditiva','memoria remota','participación']::text[], '8-10 min', 8, 10, '2 veces/semana o según plan individual', 'DCL, demencia leve y moderada con canciones muy familiares.', 'Puede seguir melodías o producir palabras/frases conocidas.', 'Facilitar acceso verbal mediante melodía y memoria musical familiar.', 'Canción muy conocida para la persona.', '["Reproducir/cantar una canción conocida.", "Detenerse antes de una palabra o frase familiar sin mostrar la letra completa.", "Dar tiempo para que la persona continúe.", "Si no aparece, completar juntos y seguir cantando sin corregir."]'::jsonb, 'Pausas muy predecibles → menos predecibles → cantar sin apoyo de grabación.', 'Demencia moderada: el familiar canta y deja solo la última palabra; avanzada: cantar juntos sin exigir completar.', 'No transformar la actividad en prueba de memoria de letras.', '{"gancho": "🧠 ¿Sabías que cantar canciones conocidas puede ayudarnos a recordar palabras y mantener la atención?", "evidencia": "La investigación ha encontrado pequeños beneficios en algunas habilidades mentales cuando las personas mayores participan activamente en actividades musicales. 🎶🧠✨", "cierre": "¡Por eso hoy vamos a cantar juntos, completar las canciones y disfrutar de esos recuerdos que la música nos trae!"}'::jsonb, 'Favorecer acceso verbal mediante melodía y memoria musical familiar.', true),
  ('MUS-003', 'Eco de ritmos', 'musica'::public.resource_modulo, 'actividad'::public.task_tipo, 'ritmo + atención', array['atención auditiva','memoria de trabajo','secuenciación','coordinación']::text[], '8-10 min', 8, 10, '2 veces/semana o según plan individual', 'Preventivo, DCL y demencia leve-moderada.', 'Puede imitar una secuencia de palmadas o golpes suaves.', 'Entrenar atención, memoria de trabajo, secuenciación e inhibición.', 'Manos o instrumento de percusión sencillo.', '["Realizar un patrón de dos golpes/palmadas.", "Pedir que lo imite.", "Aumentar a tres golpes cuando lo domine.", "Alternar intensidad o pausa para crear una regla."]'::jsonb, '2 pulsos → 3-4 → patrones con pausa → respuesta inversa.', 'Demencia moderada: mantener patrones de 1-2 pulsos y hacerlo simultáneamente.', 'Usar volumen bajo/moderado. Si se acelera o agita, volver a un ritmo regular y simple.', '{"gancho": "🧠 ¿Sabías que repetir un ritmo que escuchamos ayuda a trabajar la atención y la memoria?", "evidencia": "Los estudios sobre actividades musicales han encontrado beneficios en diferentes habilidades mentales en personas mayores con deterioro cognitivo. 🥁🧠✨", "cierre": "¡Por eso hoy vamos a estimular nuestra atención, memoria, coordinación y capacidad para seguir secuencias mientras imitamos diferentes ritmos!"}'::jsonb, 'Favorecer el entrenamiento de atención, memoria de trabajo, secuenciación e inhibición.', true),
  ('MUS-004', 'Ritmo y movimiento', 'musica'::public.resource_modulo, 'actividad'::public.task_tipo, 'música + dual task', array['ritmo','inhibición','coordinación','atención','movimiento']::text[], '8-10 min', 8, 10, '2 veces/semana o según plan individual', 'Preventivo, DCL, demencia leve; cualquier nivel motor con adaptación.', 'Puede realizar movimientos rítmicos simples.', 'Combinar sincronización rítmica, coordinación motora y atención.', 'Música con pulso claro.', '["Marcar el pulso con palmas o pies.", "Agregar movimiento alterno de brazos.", "Cuando la música se detenga, detener el movimiento.", "Reiniciar cuando vuelva el sonido."]'::jsonb, 'Sentado → de pie → cambio de movimiento por señal → añadir categoría verbal.', 'Motor Rojo: toda la actividad sentada. Demencia moderada: imitación simultánea.', 'Controlar volumen, velocidad y seguridad postural.', '{"gancho": "🧠 ¿Sabías que seguir el ritmo de una canción mientras nos movemos nos ayuda a trabajar la atención y la coordinación?", "evidencia": "La investigación ha encontrado beneficios tanto en las actividades musicales activas como en las actividades que combinan movimiento y retos mentales. 🎵🧠✨", "cierre": "¡Por eso hoy vamos a estimular nuestro ritmo, atención, coordinación, control de nuestras respuestas y movimiento mientras seguimos la música!"}'::jsonb, 'Favorecer la combinación de sincronización rítmica, coordinación motora y atención.', true),
  ('MUS-005', 'Categorías al compás', 'musica'::public.resource_modulo, 'actividad'::public.task_tipo, 'música + fluencia', array['fluencia','atención','velocidad de procesamiento','inhibición']::text[], '8-10 min', 8, 10, '2 veces/semana o según plan individual', 'Preventivo y DCL; demencia leve con adaptación.', 'Puede producir palabras por categoría.', 'Trabajar acceso semántico, velocidad de procesamiento y control rítmico.', 'Metrónomo suave o canción instrumental con pulso estable.', '["Elegir una categoría sencilla.", "Decir una palabra cada dos o cuatro pulsos, sin buscar velocidad alta.", "Si se queda en blanco, ofrecer una pista.", "Cambiar de categoría después de un bloque corto."]'::jsonb, 'Ritmo lento → moderado → alternar categorías por señal.', 'Demencia leve: familiar y persona alternan respuestas.', 'El ritmo debe ayudar a organizar, no presionar. Disminuir velocidad si aumenta el error.', '{"gancho": "🧠 ¿Sabías que combinar música y palabras nos ayuda a trabajar la rapidez para encontrar respuestas y mantener la atención?", "evidencia": "Las revisiones en personas con deterioro cognitivo han encontrado mejoras en algunas habilidades mentales y, en algunos estudios, en la fluidez verbal. 🎵🗣️✨", "cierre": "¡Por eso hoy vamos a estimular nuestra fluidez, atención, rapidez para responder y control de nuestras respuestas mientras seguimos el compás!"}'::jsonb, 'Favorecer acceso semántico, velocidad de procesamiento y control rítmico.', true),
  ('MUS-006', 'Percusión por secuencias', 'musica'::public.resource_modulo, 'actividad'::public.task_tipo, 'música activa', array['secuenciación','coordinación','memoria de trabajo','atención']::text[], '8-10 min', 8, 10, '2 veces/semana o según plan individual', 'Preventivo, DCL, demencia leve-moderada.', 'Puede sostener o golpear un instrumento seguro.', 'Entrenar secuenciación, coordinación bilateral, memoria de trabajo y atención.', 'Maracas, tambor pequeño, claves o superficies seguras.', '["Asignar dos sonidos diferentes a dos acciones.", "Modelar una secuencia corta: A-B-A.", "Pedir imitación.", "Repetir y cambiar la secuencia."]'::jsonb, '2 sonidos → 3 sonidos → secuencia más larga → cambio de regla.', 'Demencia moderada: tocar al mismo tiempo que el familiar; no exigir recuerdo diferido.', 'Evitar instrumentos pesados, frágiles o muy ruidosos.', '{"gancho": "🧠 ¿Sabías que participar activamente en actividades musicales tiene beneficios para nuestras habilidades mentales?", "evidencia": "Un meta-análisis en personas con deterioro cognitivo encontró una mejora pequeña pero significativa en la cognición al participar en actividades musicales. 🥁🧠✨", "cierre": "¡Por eso hoy vamos a estimular nuestra memoria, atención, coordinación y capacidad para seguir secuencias mientras hacemos percusión!"}'::jsonb, 'Favorecer el entrenamiento de secuenciación, coordinación bilateral, memoria de trabajo y atención.', true),
  ('MUS-007', 'Playlist para regular el estado de ánimo', 'musica'::public.resource_modulo, 'actividad'::public.task_tipo, 'escucha musical personalizada', array['regulación emocional','participación','conexión social','autobiográfica']::text[], '10-15 min', 10, 15, '2 veces/semana o según plan individual', 'Demencia leve-moderada; también cuidadores con objetivo de interacción.', 'Familia conoce música preferida y puede observar respuesta.', 'Utilizar música preferida como apoyo para conexión, calma o activación según respuesta individual.', 'Playlist breve personalizada.', '["Seleccionar 3-5 canciones realmente preferidas por la persona.", "Elegir una según objetivo: conexión, actividad tranquila o transición.", "Observar conducta antes, durante y después.", "Registrar en la app si produjo calma, activación, canto, interacción o malestar."]'::jsonb, 'Construir perfiles de respuesta por canción y momento del día.', 'En demencia avanzada usar fragmentos breves y detener si hay signos de incomodidad.', 'Esta actividad domiciliaria no debe etiquetarse como musicoterapia. Individualizar siempre: una canción alegre para el cuidador puede no serlo para la persona.', '{"gancho": "🧠 ¿Sabías que la música puede ayudarnos a mejorar nuestro bienestar emocional y conectar con los demás?", "evidencia": "Una revisión Cochrane de 2025 encontró beneficios de las intervenciones basadas en música en el bienestar emocional y la conducta de personas con demencia. 🎵❤️✨", "cierre": "¡Por eso hoy vamos a estimular nuestra regulación emocional, participación, conexión social y recuerdos personales a través de una playlist especial!"}'::jsonb, 'Favorecer el uso de música preferida como apoyo para conexión, calma o activación según respuesta individual.', true),
  ('MUS-008', 'Conversación musical guiada', 'musica'::public.resource_modulo, 'actividad'::public.task_tipo, 'música + lenguaje + vínculo', array['lenguaje','juicio simple','preferencia','emoción','interacción social']::text[], '8-10 min', 8, 10, '2 veces/semana o según plan individual', 'DCL, demencia leve y moderada.', 'Puede escuchar y responder verbal o no verbalmente.', 'Usar música como facilitador de conversación, elección y participación social.', 'Dos canciones contrastantes y conocidas.', '["Escuchar un fragmento breve de la primera canción.", "Preguntar algo simple: «¿Le gusta?», «¿le da calma o energía?»", "Escuchar la segunda y comparar.", "Explorar cuál elegiría para bailar, descansar, viajar o celebrar.", "Registrar preferencias para futuras asignaciones."]'::jsonb, 'Elección binaria → justificar elección → asociar a una etapa de vida.', 'Demencia moderada: respuestas sí/no, gesto, sonrisa o elección visual.', 'Respetar rechazo y silencio. No mantener música de fondo permanente si la persona no la disfruta.', '{"gancho": "🧠 ¿Sabías que la música favorece la participación y la interacción con otras personas?", "evidencia": "La investigación en personas con demencia ha encontrado beneficios en la participación y la conducta social al utilizar actividades musicales. 🎵💬❤️", "cierre": "¡Por eso hoy vamos a estimular nuestro lenguaje, capacidad para elegir, emociones e interacción social mientras escuchamos y conversamos sobre diferentes canciones!"}'::jsonb, 'Favorecer una participación segura y significativa mediante esta actividad.', true),
  ('REM-001', 'Mi línea de vida', 'reminiscencia'::public.resource_modulo, 'actividad'::public.task_tipo, 'reminiscencia autobiográfica estructurada', array['memoria autobiográfica','orientación temporal','identidad','lenguaje','regulación emocional']::text[], '10-15 min', 10, 15, '2 veces/semana o según plan individual', 'Preventivo, DCL y demencia leve; versión simplificada en demencia moderada.', 'Puede conversar sobre al menos algunos periodos vitales o la familia dispone de información biográfica.', 'Construir una narrativa de vida centrada en experiencias significativas y recursos personales.', 'Fotografías, fechas aproximadas, tarjetas de etapas vitales.', '["Elegir una etapa: infancia, juventud, trabajo, familia o actualidad.", "Presentar 1-3 fotografías u objetos relacionados.", "Preguntar por personas, lugares, actividades y emociones, sin exigir fechas exactas.", "Resumir al final una idea positiva o significativa que haya surgido.", "Registrar qué temas generan mayor conexión para futuras actividades."]'::jsonb, 'Una etapa → varias etapas → ordenar hitos → construir álbum/línea de vida digital.', 'Demencia moderada: trabajar una fotografía por vez, aportar nombres y contexto y usar preguntas cerradas.', 'No corregir detalles autobiográficos menores si no comprometen seguridad. Si aparece angustia sostenida, cambiar de tema y priorizar contención.', '{"gancho": "🧠 ¿Sabías que recordar momentos importantes de nuestra vida puede ayudarnos a mantener vivos nuestros recuerdos y fortalecer nuestra identidad?", "evidencia": "Los meta-análisis sobre reminiscencia han encontrado beneficios en la memoria, el bienestar emocional y la calidad de vida de personas con deterioro cognitivo. 📸❤️✨", "cierre": "¡Por eso hoy vamos a recorrer diferentes etapas de nuestra vida, recordar momentos especiales y conversar sobre las personas, lugares y experiencias que han sido importantes para nosotros!"}'::jsonb, 'Favorecer una participación segura y significativa mediante esta actividad.', true),
  ('REM-002', 'Una fotografía, una conversación', 'reminiscencia'::public.resource_modulo, 'actividad'::public.task_tipo, 'reminiscencia visual', array['memoria autobiográfica','lenguaje','reconocimiento','identidad','conexión social']::text[], '10-15 min', 10, 15, '2 veces/semana o según plan individual', 'DCL, demencia leve y moderada.', 'Responde a imágenes familiares o puede participar verbal/no verbalmente.', 'Usar una fotografía como clave para facilitar conversación y vínculo.', 'Una fotografía familiar o de un lugar significativo.', '["Mostrar la fotografía y dar contexto si es necesario.", "Evitar comenzar con «¿quién es?»; preferir «Esta es Ana, su hermana…».", "Preguntar por actividades, sensaciones o costumbres relacionadas.", "Validar gestos, sonrisas y emociones como respuestas.", "Finalizar con una frase de conexión: «Qué bonito recordar este paseo juntos»."]'::jsonb, 'Foto única → dos fotos de una época → comparar etapas → álbum temático.', 'Demencia moderada: aportar la información y permitir que la persona reaccione sin demanda de recuerdo.', 'Evitar insistencia ante falta de reconocimiento.', '{"gancho": "🧠 ¿Sabías que mirar fotografías significativas ayuda a despertar recuerdos y facilita la conversación?", "evidencia": "Las investigaciones sobre reminiscencia muestran mejores resultados cuando se utilizan recuerdos personales y se comparten con otras personas. 📷❤️✨", "cierre": "¡Por eso hoy vamos a mirar una fotografía especial, recordar lo que vivimos y conversar juntos sobre las personas, lugares y momentos que aparecen en ella!"}'::jsonb, 'Favorecer una participación segura y significativa mediante esta actividad.', true),
  ('REM-003', 'Objetos de mi historia', 'reminiscencia'::public.resource_modulo, 'actividad'::public.task_tipo, 'reminiscencia con objetos', array['memoria semántica','autobiográfica','praxias','identidad ocupacional','regulación emocional']::text[], '10-15 min', 10, 15, '2 veces/semana o según plan individual', 'DCL y demencia leve-moderada; adaptable a avanzada.', 'Existe un objeto seguro ligado a un oficio, hobby, hogar o rol familiar.', 'Conectar con roles y capacidades preservadas mediante objetos significativos.', 'Utensilio de cocina, herramienta segura, costura, cartera, brocha, libro, etc.', '["Presentar el objeto y permitir exploración.", "Preguntar primero para qué se usaba, no necesariamente cómo se llama.", "Modelar el gesto si no aparece.", "Explorar quién lo usaba, dónde y en qué etapa.", "Reconocer el rol: «Usted cocinaba mucho para su familia»."]'::jsonb, 'Objeto visible → varios objetos de un mismo rol → ordenar una secuencia funcional.', 'Demencia avanzada: manipulación, gesto y comentario biográfico del familiar.', 'Priorizar objetos grandes, limpios y seguros.', '{"gancho": "🧠 ¿Sabías que los objetos que han formado parte de nuestra vida pueden ayudarnos a conectar con recuerdos, roles y experiencias importantes?", "evidencia": "La reminiscencia utiliza objetos y otras claves personales para reforzar la continuidad de nuestra identidad y la comunicación. 👜🧠❤️", "cierre": "¡Por eso hoy vamos a explorar un objeto especial, recordar para qué lo usábamos y conversar sobre las personas, actividades y momentos relacionados con él!"}'::jsonb, 'Favorecer una participación segura y significativa mediante esta actividad.', true),
  ('REM-004', 'La receta de mi familia', 'reminiscencia'::public.resource_modulo, 'actividad'::public.task_tipo, 'reminiscencia sensorial y cultural', array['memoria autobiográfica','semántica','secuenciación','olfato','identidad cultural','emoción']::text[], '10-15 min', 10, 15, '2 veces/semana o según plan individual', 'DCL, demencia leve y moderada.', 'Historia familiar vinculada a cocina y tolerancia a aromas/alimentos.', 'Evocar rutinas y vínculos familiares mediante ingredientes y recetas.', 'Fotografía de comida, especias/aromas seguros, utensilio.', '["Elegir una receta significativa.", "Presentar un aroma o fotografía.", "Preguntar quién la preparaba y en qué ocasiones.", "Reconstruir algunos pasos sin exigir exactitud.", "Si es apropiado, terminar hablando de una tradición familiar asociada."]'::jsonb, 'Un ingrediente → varios ingredientes → ordenar pasos → crear ficha digital de receta e historia.', 'Demencia moderada: ofrecer opciones y narrar juntos.', 'No utilizar degustación automática desde la app sin filtros de disfagia, alergias y dieta.', '{"gancho": "🧠 ¿Sabías que los aromas, ingredientes y recetas familiares pueden despertar recuerdos de momentos importantes y mantener vivas nuestras tradiciones?", "evidencia": "La reminiscencia ha demostrado beneficios en el bienestar emocional y la calidad de vida, especialmente cuando se relaciona con experiencias personales. 🍲❤️✨", "cierre": "¡Por eso hoy vamos a recordar una receta especial, hablar de quién la preparaba y reconstruir juntos algunos de sus pasos y las historias que la acompañan!"}'::jsonb, 'Favorecer una participación segura y significativa mediante esta actividad.', true),
  ('REM-005', 'Mi música, mi momento', 'reminiscencia'::public.resource_modulo, 'actividad'::public.task_tipo, 'reminiscencia musical + regulación', array['memoria autobiográfica','emoción','identidad','conexión','regulación emocional']::text[], '10-15 min', 10, 15, '2 veces/semana o según plan individual', 'DCL y demencia leve-moderada.', 'Se conocen preferencias musicales reales de la persona.', 'Usar música personalmente significativa para facilitar recuerdo y observar su efecto regulador.', '1-2 canciones significativas.', '["Elegir una canción vinculada a una etapa conocida.", "Preguntar primero cómo le hace sentir.", "Explorar si aparece una persona, lugar o actividad.", "Observar si aumenta calma, activación, canto o interacción.", "Registrar la respuesta para construir un perfil musical personalizado."]'::jsonb, 'Una canción → playlist por etapas → seleccionar música según objetivo de calma o activación.', 'Demencia moderada/avanzada: escuchar juntos, cantar o acompañar con movimiento sin exigir relato.', 'Actividad musical domiciliaria ≠ musicoterapia profesional. No asumir que música lenta siempre calma o música alegre siempre activa.', '{"gancho": "🧠 ¿Sabías que una canción especial puede despertar recuerdos y emociones, y favorecer momentos de conexión?", "evidencia": "La investigación ha encontrado beneficios de las intervenciones basadas en música en el bienestar emocional y la conducta de personas con demencia. 🎵❤️✨", "cierre": "¡Por eso hoy vamos a escuchar una canción importante, recordar lo que nos hace sentir y descubrir qué personas, lugares o momentos nos trae a la memoria!"}'::jsonb, 'Favorecer una participación segura y significativa mediante esta actividad.', true),
  ('REM-006', 'Un recuerdo que me da calma', 'reminiscencia'::public.resource_modulo, 'actividad'::public.task_tipo, 'reminiscencia positiva guiada', array['regulación emocional','autobiográfica','atención interna','lenguaje emocional']::text[], '10-15 min', 10, 15, '2 veces/semana o según plan individual', 'Preventivo, DCL y demencia leve; uso muy guiado en moderada.', 'Puede identificar o responder a una experiencia asociada a seguridad, afecto o bienestar.', 'Utilizar un recuerdo seguro como recurso de regulación, sin negar emociones actuales.', 'Foto, objeto o música asociada a una experiencia de seguridad/bienestar.', '["Seleccionar previamente un recuerdo que la familia sepa que suele ser agradable.", "Presentar una sola clave.", "Preguntar qué sensación corporal o emocional aparece.", "Invitar a describir un detalle concreto: lugar, persona, sonido o actividad.", "Cerrar orientando al presente: «Estamos aquí juntos y podemos volver a esta música/foto cuando quiera»."]'::jsonb, 'Clave única → combinar dos claves → crear banco personal de recursos reguladores.', 'Demencia moderada: familiar narra brevemente la escena y observa respuesta.', 'No usar «pensamiento positivo» para invalidar tristeza. Si aumenta angustia, detener.', '{"gancho": "🧠 ¿Sabías que recordar experiencias agradables puede apoyar nuestro bienestar emocional?", "evidencia": "Los meta-análisis sobre reminiscencia han encontrado beneficios en el bienestar y la calidad de vida de personas con deterioro cognitivo. 🌿❤️✨", "cierre": "¡Por eso hoy vamos a traer a la mente un recuerdo que nos haga sentir bien, hablar sobre él y conectar con las sensaciones y emociones que nos transmite!"}'::jsonb, 'Favorecer el uso de un recuerdo seguro como recurso de regulación, sin negar emociones actuales.', true),
  ('REM-007', 'Álbum digital de vida', 'reminiscencia'::public.resource_modulo, 'actividad'::public.task_tipo, 'reminiscencia digital personalizada', array['identidad','autobiográfica','comunicación','participación social']::text[], '10-15 min', 10, 15, '2 veces/semana o según plan individual', 'DCL y demencia leve; moderada con acompañamiento.', 'Familia puede aportar fotos, nombres, música y contexto.', 'Crear un recurso digital personalizado que facilite conversaciones recurrentes.', 'App IntegraMente, fotografías, audios breves, nombres y etiquetas.', '["Seleccionar 5-10 elementos significativos.", "Añadir contexto breve: quién, dónde, etapa y por qué es importante.", "Presentar pocos elementos por sesión.", "Permitir que el familiar converse y aporte claves.", "Registrar qué elementos generan mayor participación."]'::jsonb, 'Álbum básico → capítulos por etapa → incorporar audio/música → historias familiares compartidas.', 'Demencia moderada: navegación a cargo del familiar, pantalla simple y un estímulo por vez.', 'No presentar la modalidad digital como superior de forma definitiva. Proteger privacidad y consentimiento para fotos/historias.', '{"gancho": "🧠 ¿Sabías que guardar fotografías y recuerdos personales puede facilitar conversaciones y mantener viva nuestra historia?", "evidencia": "Una revisión de 2025 encontró resultados favorables para la reminiscencia digital frente a la atención habitual, especialmente cuando está personalizada y permite compartir con otras personas. 📱❤️✨", "cierre": "¡Por eso hoy vamos a crear un álbum con fotografías y recuerdos importantes para conversar, compartir historias y mantener presentes momentos especiales de nuestra vida!"}'::jsonb, 'Favorecer una experiencia que permita un recurso digital personalizado que facilite conversaciones recurrentes.', true),
  ('REM-008', 'Celebraciones y tradiciones', 'reminiscencia'::public.resource_modulo, 'actividad'::public.task_tipo, 'reminiscencia cultural', array['identidad','orientación temporal','autobiográfica','pertenencia','regulación emocional']::text[], '10-15 min', 10, 15, '2 veces/semana o según plan individual', 'DCL, demencia leve y moderada.', 'Tradiciones culturales/religiosas/familiares conocidas y aceptadas por la persona.', 'Conectar con rutinas y tradiciones significativas que aportan continuidad personal.', 'Fotografías, música, objetos o aromas de una celebración.', '["Elegir una tradición significativa.", "Presentar uno o dos estímulos relacionados.", "Conversar sobre cómo se celebraba, con quién y qué se hacía.", "Comparar suavemente pasado y presente sin exigir precisión.", "Finalizar con una actividad pequeña relacionada si es apropiado."]'::jsonb, 'Una tradición → calendario autobiográfico anual → comparar generaciones.', 'Demencia moderada: narración compartida y estímulos simples.', 'Personalizar según cultura y creencias; nunca asumir tradiciones por edad o procedencia.', '{"gancho": "🧠 ¿Sabías que recordar nuestras celebraciones y tradiciones puede fortalecer el sentido de identidad y pertenencia?", "evidencia": "La investigación sobre reminiscencia ha encontrado beneficios en la calidad de vida y el bienestar emocional, especialmente cuando se adapta a la historia personal y se comparte con otras personas. 🎉❤️✨", "cierre": "¡Por eso hoy vamos a recordar una celebración especial, conversar sobre cómo la vivíamos y compartir las costumbres, personas y momentos que forman parte de nuestra historia!"}'::jsonb, 'Favorecer una participación segura y significativa mediante esta actividad.', true),
  ('REM-009', 'Historia de fortalezas', 'reminiscencia'::public.resource_modulo, 'actividad'::public.task_tipo, 'revisión de vida centrada en recursos', array['identidad','autoestima','metacognición','regulación emocional','lenguaje']::text[], '10-15 min', 10, 15, '2 veces/semana o según plan individual', 'Preventivo, DCL y demencia leve.', 'Puede reflexionar sobre logros, roles o estrategias de afrontamiento.', 'Reconectar con capacidades, roles y estrategias que han sido importantes a lo largo de la vida.', 'Tarjetas con preguntas, fotos o hitos.', '["Elegir un reto pasado que la persona haya superado.", "Preguntar qué hizo, quién la ayudó y qué aprendió.", "Identificar una fortaleza concreta.", "Relacionar esa fortaleza con una situación actual sencilla.", "Registrar la fortaleza en un banco personal."]'::jsonb, 'Una fortaleza → mapa de recursos → integrar a plan de bienestar.', 'En DCL usar preguntas concretas y apoyos visuales.', 'No convertir conflictos vitales complejos en una actividad automatizada.', '{"gancho": "🧠 ¿Sabías que recordar los retos que hemos superado puede ayudarnos a reconocer nuestras capacidades y fortalecer nuestra autoestima?", "evidencia": "La reminiscencia ha demostrado beneficios en el bienestar y la calidad de vida, además de apoyar la continuidad de nuestra identidad. 💪❤️✨", "cierre": "¡Por eso hoy vamos a recordar un reto que superamos, descubrir qué nos ayudó a lograrlo y reconocer una fortaleza que todavía forma parte de nosotros!"}'::jsonb, 'Favorecer la reconexión con capacidades, roles y estrategias que han sido importantes a lo largo de la vida.', true),
  ('REM-010', 'Reminiscencia compartida con la familia', 'reminiscencia'::public.resource_modulo, 'actividad'::public.task_tipo, 'reminiscencia social', array['conexión social','comunicación','identidad','afecto','regulación interpersonal']::text[], '10-15 min', 10, 15, '2 veces/semana o según plan individual', 'DCL, demencia leve-moderada y familias disponibles.', 'Existe un familiar capaz de acompañar sin corregir ni confrontar.', 'Convertir el recuerdo en una experiencia de vínculo, no en una prueba de memoria.', 'Una foto, canción u objeto.', '["El familiar presenta la clave y aporta contexto.", "Usar frases como «Yo recuerdo que…» en vez de «¿se acuerda?»", "Compartir también su propio recuerdo.", "Observar qué emoción aparece y ajustar el ritmo.", "Terminar con una actividad compartida breve: escuchar, mirar fotos o tomar café."]'::jsonb, 'Interacción de 5 minutos → 10-15 minutos → álbum o playlist compartida.', 'Demencia moderada: familiar lleva la narración y permite respuestas mínimas.', 'Enseñar al cuidador a no discutir por discrepancias autobiográficas no peligrosas.', '{"gancho": "🧠 ¿Sabías que compartir recuerdos con la familia ayuda a fortalecer la comunicación y el vínculo?", "evidencia": "Las revisiones recientes muestran buena participación en formatos de reminiscencia compartidos, y la interacción social es un elemento importante en estos espacios. 👨‍👩‍👧‍👦❤️✨", "cierre": "¡Por eso hoy vamos a compartir una fotografía, canción u objeto especial, contar nuestros propios recuerdos y disfrutar juntos de ese momento!"}'::jsonb, 'Favorecer una experiencia que permita convertir el recuerdo en una experiencia de vínculo, no en una prueba de memoria.', true);
